draw((9,9)--(1,9));
draw((1,9)--(1,1));
fill((1,1)--(1,9)--(9,9)--(9,1)--cycle,gray);
draw((9,10.5)--(9,11));
draw((10,10.5)--(10,11));
draw((9,10.75)--(10,10.75));
label("20'",(9.5,11),N);
draw((10.5,9)--(11,9));
draw((10.5,10)--(11,10));
draw((10.75,9)--(10.75,10));
label("20'",(11,9.5),E);
label("400'",(5,9),S);
label("400'",(9,5),W);
[/asy]

